begin;
create or replace function pg_temp.assert_true(value boolean,message text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'assertion failed: %',message; end if; end$$;
insert into auth.users(id) values ('11030100-0000-4000-8000-000000000001'),('11030100-0000-4000-8000-000000000002'),('11030100-0000-4000-8000-000000000003');
insert into public.user_roles(user_id,role) values ('11030100-0000-4000-8000-000000000001','professional'),('11030100-0000-4000-8000-000000000003','professional');
insert into public.professional_profiles(user_id,professional_name) values ('11030100-0000-4000-8000-000000000001','Ciclos');
insert into public.bodyweight_entries(id,user_id,measured_on,weight_kg) values('11030100-0000-4000-8000-000000000020','11030100-0000-4000-8000-000000000002','2026-11-01',75);
insert into public.body_measurement_checkins(id,user_id,measured_on,measurements_cm) values('11030100-0000-4000-8000-000000000021','11030100-0000-4000-8000-000000000002','2026-11-01','{"waist":80}');
set local role authenticated;
select set_config('request.jwt.claim.sub','11030100-0000-4000-8000-000000000002',true);
select public.save_athlete_plan(0,'daily','{"week":{"2":"11030100-0000-4000-8000-000000000010"},"dayPlan":{"2026-11-03":"rest"}}','[{"id":"11030100-0000-4000-8000-000000000010","title":"Pessoal vivo","prescription":{"ex":[{"id":"0043","sets":2,"reps":10,"weight":25}]}}]');
do $$ declare request uuid; r1 uuid; r2 uuid; assignment uuid; library uuid; rev bigint; data jsonb; frozen jsonb; begin
 -- The reusable code is discoverable; asking does not create an active relationship.
 request := (public.request_professional_link('CICLOS')).id;
 perform pg_temp.assert_true(not has_table_privilege('authenticated','public.professional_link_requests','INSERT'),'requests can only be created through the protected RPC');
 begin perform public.professional_link_request_detail(request); raise exception 'student read professional request DTO'; exception when insufficient_privilege then null; end;
 perform pg_temp.assert_true((public.request_professional_link('CICLOS')).id=request,'duplicate pending request is idempotent');
 perform pg_temp.assert_true(not exists(select 1 from public.professional_student_relationships where student_user_id=auth.uid()),'student request is not active');
 begin perform public.accept_professional_link_request(request); raise exception 'student accepted own request'; exception when insufficient_privilege then null; end;
 perform set_config('request.jwt.claim.sub','11030100-0000-4000-8000-000000000003',true);
 perform pg_temp.assert_true((select count(*)=0 from public.professional_link_requests where id=request),'RLS hides requests from other professionals');
 begin perform public.professional_link_request_detail(request); raise exception 'other professional read request DTO'; exception when insufficient_privilege then null; end;
 begin perform public.accept_professional_link_request(request); raise exception 'other professional accepted request'; exception when insufficient_privilege then null; end;
 begin perform public.reject_professional_link_request(request); raise exception 'other professional rejected request'; exception when insufficient_privilege then null; end;
 perform set_config('request.jwt.claim.sub','11030100-0000-4000-8000-000000000001',true);
 r1 := (public.accept_professional_link_request(request)).id;
 perform public.add_professional_student_note('11030100-0000-4000-8000-000000000002','Nota preservada do ciclo R1');
 perform pg_temp.assert_true((public.accept_professional_link_request(request)).id=r1,'double accept creates one cycle');
 perform public.save_student_plan_draft('11030100-0000-4000-8000-000000000002','V1','{"routines":[{"id":"a","name":"Peito","ex":[{"id":"0043","sets":3,"reps":10,"weight":20}]}],"week":{"1":"a","4":"a"}}',0);
 assignment := (public.send_student_plan('11030100-0000-4000-8000-000000000002',1)).id;
 perform pg_temp.assert_true((select relationship_id=r1 from public.program_assignments where id=assignment),'assignment belongs to R1');
 perform set_config('request.jwt.claim.sub','11030100-0000-4000-8000-000000000002',true);
 select id into library from public.athlete_plan_library where assignment_id=assignment;
 select revision into rev from public.athlete_schedules where user_id=auth.uid();
 data := public.apply_library_plan(library,rev);
 perform public.start_workout_execution('11030100-0000-4000-8000-000000000030',assignment,'monday','{"workoutName":"Peito realizado"}');
 perform public.complete_workout_execution('11030100-0000-4000-8000-000000000030','{"entries":[{"id":"0043","sets":[{"w":20,"r":10,"done":true}]}]}');
 perform pg_temp.assert_true(data->'schedule'->'schedule'->'week' ? '1' and not data->'schedule'->'schedule'->'week' ? '3','professional calendar and rest applied');
 -- Professional ends the cycle while the student could be offline.
 perform set_config('request.jwt.claim.sub','11030100-0000-4000-8000-000000000001',true);
 perform public.revoke_professional_relationship(r1);
 data:=public.professional_historical_student_detail('11030100-0000-4000-8000-000000000002');
 frozen:=jsonb_build_object('weights',data->'weight_history','measurements',data->'measurements');
 perform pg_temp.assert_true(jsonb_array_length(frozen->'weights')=1 and jsonb_array_length(frozen->'measurements')=1,'closed body history is retained');
 perform pg_temp.assert_true(data->'notes'->0->>'body'='Nota preservada do ciclo R1','private notes survive closure');
 perform pg_temp.assert_true((public.professional_historical_executions_page('11030100-0000-4000-8000-000000000002')->>'total')::int=1,'closed-cycle executions remain readable');
 perform pg_temp.assert_true((public.professional_students_page('', 'inactive')->>'total')::int=1,'student is inactive');
 perform pg_temp.assert_true(jsonb_array_length(public.professional_relationship_cycles('11030100-0000-4000-8000-000000000002'))=1,'R1 remains historical');
 perform set_config('request.jwt.claim.sub','11030100-0000-4000-8000-000000000002',true);
 if to_regprocedure('public.save_athlete_body(bigint,jsonb,jsonb)') is not null then
  execute $q$select public.save_athlete_body((public.load_athlete_body()->>'revision')::bigint,'[{"id":"11030100-0000-4000-8000-000000000020","date":"2026-11-01","weightKg":75},{"id":"11030100-0000-4000-8000-000000000022","date":"2026-11-03","weightKg":76}]','[{"id":"11030100-0000-4000-8000-000000000021","date":"2026-11-01","valuesCm":{"waist":80}}]')$q$;
 else
  execute $q$select public.save_athlete_body('[{"id":"11030100-0000-4000-8000-000000000020","date":"2026-11-01","weightKg":75},{"id":"11030100-0000-4000-8000-000000000022","date":"2026-11-03","weightKg":76}]','[{"id":"11030100-0000-4000-8000-000000000021","date":"2026-11-01","valuesCm":{"waist":80}}]')$q$;
 end if;
 perform set_config('request.jwt.claim.sub','11030100-0000-4000-8000-000000000001',true);
 data:=public.professional_historical_student_detail('11030100-0000-4000-8000-000000000002');
 perform pg_temp.assert_true(jsonb_build_object('weights',data->'weight_history','measurements',data->'measurements')=frozen,'later body sync cannot change closed history or expose new points');
 perform set_config('request.jwt.claim.sub','11030100-0000-4000-8000-000000000002',true);
 select revision into rev from public.athlete_schedules where user_id=auth.uid();
 perform pg_temp.assert_true((select mode='daily' and schedule->'week'='{"2":"11030100-0000-4000-8000-000000000010"}'::jsonb and schedule->'dayPlan'='{"2026-11-03":"rest"}'::jsonb and not schedule ? 'assignedProgram' from public.athlete_schedules where user_id=auth.uid()),'backend restores personal schedule');
 perform pg_temp.assert_true((select title='Pessoal vivo' and prescription->'ex'->0->>'weight'='25' from public.athlete_routines where id='11030100-0000-4000-8000-000000000010'),'personal prescription preserved');
 perform pg_temp.assert_true((public.athlete_plan_library_page()->>'total')::int=1,'old professional plan absent from current library');
 begin perform public.apply_library_plan(library,rev); raise exception 'revoked plan applied'; exception when insufficient_privilege then null; end;
 request := (public.request_professional_link('CICLOS')).id;
 perform set_config('request.jwt.claim.sub','11030100-0000-4000-8000-000000000001',true);
 r2 := (public.accept_professional_link_request(request)).id;
 perform pg_temp.assert_true(r1<>r2,'reconnection creates new ID');
 perform pg_temp.assert_true((public.professional_students_page('', 'inactive')->>'total')::int=0,'reconnected student leaves inactive');
 perform pg_temp.assert_true(jsonb_array_length(public.professional_relationship_cycles('11030100-0000-4000-8000-000000000002'))=2,'R1 and R2 remain');
 perform pg_temp.assert_true((public.professional_historical_executions_page('11030100-0000-4000-8000-000000000002')->>'total')::int=1,'reconnection preserves earlier executions');
 perform set_config('request.jwt.claim.sub','11030100-0000-4000-8000-000000000002',true);
 begin perform public.apply_library_plan(library,rev); raise exception 'old cycle plan applied after reconnection'; exception when insufficient_privilege then null; end;
 perform pg_temp.assert_true((public.athlete_plan_library_page()->>'total')::int=1,'reconnection never resurrects old plan');
 perform set_config('request.jwt.claim.sub','11030100-0000-4000-8000-000000000001',true);
 perform public.save_student_plan_draft('11030100-0000-4000-8000-000000000002','V2','{"routines":[{"id":"b","name":"Costas novas","ex":[{"id":"0043","sets":4,"reps":8,"weight":30}]}],"week":{"2":"b"}}',0);
 assignment:=(public.send_student_plan('11030100-0000-4000-8000-000000000002',1)).id;
 perform pg_temp.assert_true((select relationship_id=r2 from public.program_assignments where id=assignment),'new prescription belongs only to R2');
 perform set_config('request.jwt.claim.sub','11030100-0000-4000-8000-000000000002',true);
 select id into library from public.athlete_plan_library where assignment_id=assignment;
 data:=public.apply_library_plan(library,rev);
 perform pg_temp.assert_true(data->'schedule'->'schedule'->'week' ? '2' and not data->'schedule'->'schedule'->'week' ? '1','R2 applies only its new prescription');
 -- Student also ends a cycle, preserving its historical ID.
 perform public.revoke_professional_relationship(r2);
 perform pg_temp.assert_true((select not schedule ? 'assignedProgram' and schedule->'week'='{"2":"11030100-0000-4000-8000-000000000010"}'::jsonb from public.athlete_schedules where user_id=auth.uid()),'student closure also restores personal workspace');
 request := (public.request_professional_link('CICLOS')).id;
 perform set_config('request.jwt.claim.sub','11030100-0000-4000-8000-000000000001',true);
 perform public.reject_professional_link_request(request);
 begin perform public.accept_professional_link_request(request); raise exception 'rejected request accepted'; exception when invalid_parameter_value then null; end;
 perform pg_temp.assert_true(jsonb_array_length(public.professional_link_requests_page()->'items')=0,'resolved requests leave pending dashboard');
end $$;
-- Legacy account with live personal routines but no saved personal library snapshot.
reset role;
insert into auth.users(id) values('11030100-0000-4000-8000-000000000004');
insert into public.professional_student_relationships(id,professional_user_id,student_user_id,status) values('11030100-0000-4000-8000-000000000040','11030100-0000-4000-8000-000000000001','11030100-0000-4000-8000-000000000004','active');
set local role authenticated;
select set_config('request.jwt.claim.sub','11030100-0000-4000-8000-000000000004',true);
select public.save_athlete_plan(0,'weekly','{"week":{"2":"11030100-0000-4000-8000-000000000041"},"dayPlan":{}}','[{"id":"11030100-0000-4000-8000-000000000041","title":"Baseline pessoal","prescription":{"ex":[{"id":"0043","sets":2,"reps":12,"weight":35}]}}]');
select set_config('request.jwt.claim.sub','11030100-0000-4000-8000-000000000001',true);
select public.save_student_plan_draft('11030100-0000-4000-8000-000000000004','Legacy','{"routines":[{"id":"a","name":"Profissional","ex":[{"id":"0043","sets":3,"reps":10}]}],"week":{"1":"a"}}',0);
select public.send_student_plan('11030100-0000-4000-8000-000000000004',1);
select set_config('request.jwt.claim.sub','11030100-0000-4000-8000-000000000004',true);
select public.apply_library_plan((select id from public.athlete_plan_library where source_type='professional' and user_id=auth.uid()),1);
reset role;
-- Simulate a legacy installation without a personal snapshot, not a production delete.
delete from public.athlete_plan_library where user_id='11030100-0000-4000-8000-000000000004' and source_type='self';
set local role authenticated;
select public.revoke_professional_relationship('11030100-0000-4000-8000-000000000040');
select pg_temp.assert_true((select schedule->'week'='{}'::jsonb and schedule->'dayPlan'='{}'::jsonb and not schedule ? 'assignedProgram' from public.athlete_schedules where user_id=auth.uid()),'missing snapshot creates a safe personal baseline instead of professional calendar');
select pg_temp.assert_true((select prescription->'ex'->0->>'weight'='35' and prescription->'ex'->0->>'reps'='12' from public.athlete_routines where id='11030100-0000-4000-8000-000000000041'),'baseline preserves live personal sets reps and loads');
rollback;
